/* DependencyGraphTab / FeatureNode: 160×70 nodes, 40px node / 60px rank gaps.
   The existing graph data supplies relationships; this package lays them out without Dagre. */
function v2DagGeometry(graph) {
  const ranks={},degree={},pending=[],nodes=graph.nodes,edges=graph.edges.filter(function(e){return e.kind!=='rel';});
  nodes.forEach(function(n){ranks[n.id]=0;degree[n.id]=edges.filter(function(e){return e.to===n.id;}).length;if(!degree[n.id])pending.push(n.id);});
  for(let i=0;i<pending.length;i++){const id=pending[i];edges.filter(function(e){return e.from===id;}).forEach(function(e){ranks[e.to]=Math.max(ranks[e.to],ranks[id]+1);degree[e.to]--;if(!degree[e.to])pending.push(e.to);});}
  const groups=[];nodes.forEach(function(n){(groups[ranks[n.id]]||(groups[ranks[n.id]]=[])).push(n);});
  const width=Math.max(360,...groups.map(function(g){return g.length*200;}))+40,placed={};
  groups.forEach(function(g,r){g.forEach(function(n,i){placed[n.id]={x:(width-g.length*200)/2+i*200+20,y:20+r*130};});});
  return {nodes:placed,width:width,height:Math.max(180,groups.length*130+40)};
}
const V2_DEP_EDGE={from:{get name(){return tc("v2f.copy.w195")},token:'evolved',dash:''},block:{get name(){return tc("v2f.copy.w196")},token:'blocked',dash:'6 3'},rel:{get name(){return tc("v2f.copy.w197")},token:'related',dash:'3 3'}};
PDL_COMPONENTS.v2DependencyGraph=function(p,sc,root){
  const x=pv(p.data,sc,root),g=x.graph,geo=v2DagGeometry(g),offset=g.offset,zoom=g.zoom;
  const toolbar='<div class="mb-3 flex flex-wrap items-center justify-between gap-3 rounded-xl bg-[var(--console-card-bg)] shadow-[0_8px_22px_rgba(43,33,26,0.04)] px-3 py-2"><div class="flex items-center gap-2">'+[['connected',tc("v2f.copy.w198")],['active',tc("v2f.copy.w199")],['all',tc("v2f.copy.w074")]].map(function(o){return '<button type="button" class="rounded-lg px-2.5 py-1 text-xs font-medium transition-colors '+(x.scope===o[0]?'bg-[var(--console-active-bg)] font-semibold text-cafe':'bg-[var(--console-hover-bg)] text-cafe-secondary hover:bg-[var(--console-active-bg)]')+'"'+actAttrs('set',{path:'ws.depScope',v:o[0]})+'>'+o[1]+'</button>';}).join('')+'</div><span class="text-xs text-cafe-secondary" data-testid="mc-dep-stats">'+x.nodes+" "+tc("v2f.copy.w200")+" "+x.edges+(" "+h(tc("v2f.copy.w201"))+"</span></div>");
  const legend='<div class="mb-3 flex flex-wrap items-center gap-4 rounded-xl bg-[var(--console-card-bg)] shadow-[0_8px_22px_rgba(43,33,26,0.04)] px-3 py-2">'+['suggested','dispatched','done','open'].map(function(st){return '<span class="flex items-center gap-1"><span class="h-2 w-2 rounded-full" style="background:var(--mc-status-'+st+'-dot)"></span><span class="text-xs text-cafe-secondary">'+V2_MISSION_STATUS[st]+'</span></span>';}).join('')+("<span class=\"text-xs text-cafe-secondary\"><span style=\"color:var(--mc-edge-evolved)\">"+h(tc("v2f.copy.w202"))+"</span> · <span style=\"color:var(--mc-edge-blocked)\">"+h(tc("v2f.copy.w203"))+"</span> · <span style=\"color:var(--mc-edge-related)\">"+h(tc("v2f.copy.w204"))+"</span></span></div>");
  const edges=g.edges.map(function(e,i){const a=geo.nodes[e.from],b=geo.nodes[e.to],s=V2_DEP_EDGE[e.kind],ax=a.x+80,ay=a.y+60,bx=b.x+80,by=b.y,cy=(ay+by)/2;return '<g><defs><marker id="v2-dep-arrow-'+i+'" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="var(--mc-edge-'+s.token+')"/></marker></defs><path d="M'+ax+' '+ay+' C'+ax+' '+cy+' '+bx+' '+cy+' '+bx+' '+by+'" fill="none" stroke="var(--mc-edge-'+s.token+')" stroke-width="'+(e.kind==='rel'?1.5:2)+'" stroke-dasharray="'+s.dash+'" marker-end="url(#v2-dep-arrow-'+i+')"'+(e.kind==='rel'?' marker-start="url(#v2-dep-arrow-'+i+')"':'')+'/><text x="'+((ax+bx)/2)+'" y="'+(cy-5)+'" text-anchor="middle" font-size="11" fill="var(--mc-edge-'+s.token+')">'+s.name+'</text></g>';}).join('');
  const nodes=g.nodes.map(function(n){const xy=geo.nodes[n.id],state=n.state==='approved'?'suggested':n.state;return '<foreignObject class="g-node" x="'+xy.x+'" y="'+xy.y+'" width="160" height="80"><button xmlns="http://www.w3.org/1999/xhtml" class="w-full rounded-xl border-2 bg-[var(--console-card-bg)] px-3 py-2 shadow-sm text-left transition-shadow hover:shadow-md '+(n.done?'opacity-50':'')+'" style="border-color:var(--mc-status-'+state+'-dot);background:'+(state==='open'?'var(--console-card-bg)':'var(--mc-status-'+state+'-bg)')+';width:160px;min-height:60px" data-testid="mc-dep-node-'+h(n.id)+'"'+actAttrs('set',{path:'ws.node',v:n.id})+'><span class="flex items-center gap-1.5"><span class="h-2.5 w-2.5 rounded-full" style="background:var(--mc-status-'+state+'-dot)"></span><span class="text-xs font-bold text-cafe-secondary">'+h(n.id)+'</span></span><span class="mt-1 block text-xs leading-snug text-cafe-secondary">'+h(n.name)+'</span></button></foreignObject>';}).join('');
  const detail=x.node?'<div class="mt-3 rounded-xl bg-[var(--console-card-bg)] shadow-[0_8px_22px_rgba(43,33,26,0.04)] p-4" data-testid="mc-dep-node-detail"><div class="flex items-center justify-between"><span class="text-sm font-bold text-cafe-secondary">'+h(x.node.id)+' · '+h(V2_MISSION_STATUS[x.node.status])+'</span>'+PDL_COMPONENTS.v2Action({icon:'close',iconOnly:true,label:tc("v2f.copy.w205"),act:'set',args:{path:'ws.node',v:''}},sc,root)+'</div><p class="mt-1 text-xs text-cafe-secondary">'+h(x.node.name)+'</p>'+[['from',tc("v2f.copy.w206")],['block',tc("v2f.copy.w207")],['rel',tc("v2f.copy.w197")]].map(function(d){return x.node[d[0]].length?'<div class="mt-2 text-xs text-cafe-secondary">'+d[1]+'：'+h(x.node[d[0]].join(', '))+'</div>':'';}).join('')+'</div>':'';
  return '<section data-testid="mc-dep-graph">'+toolbar+legend+(g.nodes.length?'<div class="h-[500px] w-full overflow-hidden rounded-xl bg-[var(--console-card-bg)] shadow-[0_8px_22px_rgba(43,33,26,0.04)]"><svg class="v2-dependency-svg graph pan h-full w-full" data-pan="wsPan" viewBox="'+[-offset[0],-offset[1],geo.width/zoom,geo.height/zoom].join(' ')+("\" role=\"img\" aria-label=\""+h(tc("v2f.copy.w208"))+"\">")+edges+nodes+'</svg></div>':("<div class=\"flex items-center justify-center rounded-xl bg-[var(--console-card-bg)] py-16 text-sm text-cafe-secondary\">"+h(tc("v2f.copy.w209"))+"</div>"))+detail+'</section>';
};
