  if(o.mode==='live'){const a=o.actions.find(function(a){return a.id===(o.status&&o.status.armed?o.revokeId:o.armId);});return '<div class="space-y-2"><p class="text-xs text-cafe-secondary">'+h(o.status?o.status.label:tc('pcf.checking'))+(o.status&&o.status.seconds?' · '+h(o.status.seconds)+'s':'')+'</p>'+(a?act(a):'')+'</div>';}
  const connected=o.phase==='connected'||o.phase==='disconnecting',id=connected?o.offId:o.currentId||o.firstId,a=o.actions.find(function(a){return a.id===id;});
