PDL_COMPONENTS.v2Tiles=function(p,sc,root){return '<div class="grid grid-cols-2 gap-3">'+pvList(p.from,sc,root).map(function(x){return '<button type="button" class="rounded-xl bg-[var(--console-card-bg)] p-4 text-left"'+actAttrs(x.act||p.act,x.args)+'><strong class="text-sm text-cafe">'+h(x.title||x.label)+'</strong><p class="mt-1 text-xs text-cafe-muted">'+h(x.sub)+'</p></button>';}).join('')+'</div>';};
PDL_COMPONENTS.v2Tree=function(p,sc,root){const q=pvDeep(p,root,sc),nodes=q.nodes,open=S.folds[FOLD_TREE+q.id]||(S.folds[FOLD_TREE+q.id]={}),loaded=S.treeLoaded[q.id]||(S.treeLoaded[q.id]={});const walk=function(path){return (nodes[path]||[]).map(function(x){const n=p.item?Object.assign({},x,pvDeep(p.item,root,x)):x,sel=p.select?pvDeep(p.select,root,n):null,a=sel||{act:n.dir?'fold':p.fileAct,args:n.dir?{f:'tree',l:q.id,p:n.path}:pvArgsObj(p.fileArgs,n,root)},row=v2Row(p.row,n,root,a);if(!n.dir)return row;if(q.ready)loaded[n.path]=true;return '<div class="lr-node space-y-1" data-open="'+!!open[n.path]+'">'+row+'<div class="lr-kids space-y-1 pl-4">'+(loaded[n.path]?walk(n.path):open[n.path]?'<p class="py-2 text-xs text-cafe-muted">'+h(tc('common.loading'))+'</p>':'')+'</div></div>';}).join('');};return '<div class="space-y-1">'+walk('')+'</div>';};
PDL_COMPONENTS.v2Tabs=function(p,sc,root){return '<div class="flex flex-wrap items-center gap-1" role="tablist">'+pvList(p.from,sc,root).map(function(x){const selected=pv(p.selected,x,root);return '<span class="inline-flex items-center"><button type="button" role="tab" aria-selected="'+!!selected+'" class="rounded-lg px-3 py-2 text-sm '+(selected?'bg-[var(--console-active-bg)] font-semibold':'text-cafe-muted')+'"'+actAttrs(p.act,pvArgsObj(p.args,x,root))+' data-tip="'+pvText(p.tip,x,root)+'">'+v2Part(p.parts,x,root)+'</button>'+v2Controls(p.close,x,root)+'</span>';}).join('')+v2Controls(p.after,sc,root)+'</div>';};
PDL_COMPONENTS.v2KVList=function(p,sc,root){
 const q=pvDeep(p,root,sc),rs=q.rows||[],args=function(op,i,path){return Object.assign({l:q.key},op?{op:op}:{},i==null?{}:{i:i},q.path?{path:path||q.path,shape:q.single?undefined:'pair'}:{});};
 if(q.ro)return '<div class="flex flex-wrap gap-2">'+rs.map(function(r){return '<code class="rounded bg-[var(--console-field-bg)] px-2 py-1 text-xs">'+h(r.k)+'</code>';}).join('')+'</div>';
 return '<div class="space-y-2">'+rs.map(function(r,i){return '<div class="flex items-center gap-2">'+(q.single?'':'<input class="'+V2_FIELD_CLASS+'" value="'+h(r.k)+'" data-input="'+h(q.input)+'" data-draft="'+h(q.key+':'+i+':k')+'" placeholder="'+h(q.keyPh)+'">')+'<input class="'+V2_FIELD_CLASS+'" type="'+(q.single||r.show?'text':'password')+'" value="'+h(r.v)+'" data-input="'+h(q.input)+'" data-draft="'+h(q.key+':'+i+(q.single?'':':v'))+'">'+(!q.single&&q.eye?PDL_COMPONENTS.v2Action({icon:'eye',iconOnly:true,label:tc(r.show?'kv.hide':'kv.show'),act:q.eye,args:args(null,i,q.path+'.'+i+'.2'),pressed:r.show},sc,root):'')+PDL_COMPONENTS.v2Action({icon:'delete',iconOnly:true,label:tc('common.delete'),act:q.del,args:args('del',i)},sc,root)+'</div>';}).join('')+PDL_COMPONENTS.v2Action({label:q.add,act:q.del,args:args('add')},sc,root)+'</div>';
};
PDL_COMPONENTS.v2Diff=function(p,sc,root){const q=pvDeep(p,root,sc);return '<div class="overflow-auto rounded-lg bg-[var(--console-field-bg)] font-mono text-xs">'+(q.hunks||[]).map(function(hk){return '<div class="px-3 py-2 text-cafe-muted">'+h(hk[0])+'</div>'+hk[1].map(function(l){return '<div class="px-3 '+(l[0]==='+'?'bg-conn-green-bg text-conn-green-text':l[0]==='-'?'bg-conn-red-bg text-conn-red-text':'text-cafe-secondary')+'">'+h(l[0]+' '+l[1])+'</div>';}).join('');}).join('')+'</div>';};
PDL_COMPONENTS.v2Bars=function(p,sc,root){const xs=pvList(p.from,sc,root),max=Math.max(1,...xs.map(function(x){return x.value;}));return '<div class="flex h-32 items-end gap-2">'+xs.map(function(x){return '<div class="flex h-full flex-1 flex-col justify-end text-center"><div class="rounded-t bg-cafe-accent" style="height:'+Math.round(x.value/max*100)+'%"></div><span class="text-xs text-cafe-muted">'+v2Part(p.item&&p.item.label,x,root)+'</span></div>';}).join('')+'</div>';};
PDL_COMPONENTS.v2Claim=function(p,sc,root){
 const data=pvDeep(p.data,root,sc),x=pdlChain(p.slot,data);if(!x)return PDL_COMPONENTS.v2Pre({text:{lit:typeof data[p.fallback]==='string'?data[p.fallback]:JSON.stringify(data[p.fallback],null,2)}},sc,root);
 const values={};Object.keys(x.extract||{}).forEach(function(k){const e=x.extract[k];let v;if(e.from==='tool'){const m=new RegExp(e.re).exec(data.tool);v=m?m[1]:null;}else{try{v=JSON.parse(data.result)[e.key];}catch(err){v=null;}}if(e.map&&Object.prototype.hasOwnProperty.call(e.map,String(v)))v=e.map[String(v)];if((v==null||v==='')&&e.empty!=null)v=e.empty;values[k]=v==null?'':String(v);});
 const f=function(t){return h(String(t||'').replace(/\{(\w+)\}/g,function(_,k){return values[k];}));};return '<div class="flex items-center gap-2 rounded-lg bg-[var(--console-field-bg)] p-3 text-xs text-cafe-secondary">'+v2Glyph(x.icon)+'<strong>'+f(x.title)+'</strong>'+(x.chips||[]).map(function(c){return '<span class="rounded-full bg-[var(--console-hover-bg)] px-2 py-0.5">'+f(c)+'</span>';}).join('')+'<span>'+f(x.line)+'</span><span class="ml-auto text-cafe-muted">'+h(x.by)+'</span></div>';
};
PDL_COMPONENTS.v2Typed=function(p,sc,root){const it=pv(p.data,sc,root),node=pdlTyped(p.slot,pv(p.of,sc,root));if(!node)return pvBlocks(p.blocks,sc,root);const r=node.sources?pdlSourceOf(node,it):node.vm?vmRead(node.vm,it):it;return r?pvBlocks(node.blocks,r,r):'';};
