PDL_COMPONENTS.v2MemoryPersonDetail=function(p,sc,root){const x=pv(p.data,sc,root),v=x.person;return ("<aside class=\"space-y-4 rounded-xl border border-cafe-subtle bg-[var(--console-card-bg)] p-4 md:p-6\" aria-label=\""+h(tc("v2f.copy.w243"))+"\">")+v2MemoryDetailHead(tc("v2f.copy.w243"),tc("v2f.copy.w244"))+v2MemoryFeedback(x)+'<h3 class="text-display-sm font-medium">'+h(v.displayName)+("</h3><p class=\"text-xs text-cafe-muted\">"+h(tc("v2f.copy.w245"))+" ")+h(v2MemoryDate(v.createdAt))+(v.aliases.length?" "+tc("v2f.copy.w246")+" "+h(v.aliases.join('、')):'')+'</p>'+pvBlocks(p.blocks,sc,root)+'<div class="flex flex-wrap gap-3">'+v2Controls(p.controls,sc,root)+'</div></aside>';};
PDL_COMPONENTS.v2MemoryEventDetail=function(p,sc,root){const x=pv(p.data,sc,root),v=x.event;return ("<aside class=\"space-y-4 rounded-xl border border-cafe-subtle bg-[var(--console-card-bg)] p-4 md:p-6\" aria-label=\""+h(tc("v2f.copy.w247"))+"\">")+v2MemoryDetailHead(tc("v2f.copy.w247"),tc("v2f.copy.w248"))+v2MemoryFeedback(x)+'<h3 class="text-display-sm">'+h(v.type)+'</h3><p class="text-xs text-cafe-muted">'+h(v2MemoryDate(v.timestamp))+' · '+(v.status==='retired'?tc("v2f.copy.w038"):tc("v2f.copy.w039"))+'</p><p class="whitespace-pre-wrap break-words text-sm">'+h(v.summary)+'</p>'+pvBlocks(p.blocks,sc,root)+'<div class="flex flex-wrap gap-3">'+v2Controls(p.controls,sc,root)+'</div></aside>';};
