/* CollectionGraphParts / GraphCanvas. Coordinates and edges come from the existing graph VM. */
PDL_COMPONENTS.v2Graph=function(p,sc,root){const q=pvDeep(p,root,sc),xs=pvItems(p.nodes,sc,root),nodes=xs.map(function(x){return p.item?Object.assign({},x,pvDeep(p.item,root,x)):x;}),positions={};nodes.forEach(function(x,i){positions[x.id]=[x.x==null?100+i*180:x.x,x.y==null?80:x.y];});return '<div class="relative rounded-lg bg-[var(--console-card-bg)] p-3"><svg class="h-full w-full" viewBox="'+h((q.view||[0,0,680,300]).join(' '))+'" role="img" aria-label="'+h(q.label)+'">'+pvList(p.edges,sc,root).map(function(e){const a=typeof e.from==='string'?positions[e.from]:e.from,b=typeof e.to==='string'?positions[e.to]:e.to;return '<line x1="'+a[0]+'" y1="'+a[1]+'" x2="'+b[0]+'" y2="'+b[1]+'" stroke="#94a3b8" stroke-width="1.5"/>';}).join('')+nodes.map(function(n){const xy=positions[n.id];return '<g class="cursor-pointer" role="treeitem"'+actAttrs(n.act,n.args)+'><rect x="'+(xy[0]-68)+'" y="'+(xy[1]-25)+'" width="136" height="50" rx="12" fill="'+(n.hub||n.selected?'#eff6ff':'#fffdf8')+'" stroke="'+(n.hub||n.selected?'#2563eb':'#d6cabc')+'"/><rect x="'+(xy[0]-68)+'" y="'+(xy[1]-25)+'" width="5" height="50" rx="2.5" fill="#60a5fa"/><text x="'+(xy[0]-52)+'" y="'+(xy[1]+4)+'" font-size="13" font-weight="800" fill="#1f2937">'+h(n.text||n.id)+'</text></g>';}).join('')+'</svg></div>';};
PDL_COMPONENTS.v2MemoryRelations=function(p,sc,root){const x=pv(p.data,sc,root);return '<div data-testid="collection-graph"><form class="mb-4 flex flex-col gap-2 sm:flex-row" data-form="cafeGraph"><input id="mem-gq" class="min-w-0 flex-1 h-9 w-full rounded-lg border border-transparent bg-[var(--console-field-bg)] px-3 text-compact text-cafe outline-none placeholder:text-cafe-muted transition focus:ring-1 focus:ring-[var(--console-input-stroke)]" data-testid="graph-anchor-input" value="'+h(x.q)+("\" placeholder=\""+h(tc("v2h.memory.graphPlaceholder"))+"\" data-input=\"cafeField\"><button class=\"h-9 shrink-0 rounded-lg bg-cafe-accent px-3 text-compact font-semibold text-[var(--cafe-surface)] transition-colors hover:bg-cafe-interactive disabled:opacity-50 sm:w-auto\" type=\"submit\">"+h(tc("v2h.memory.graphFetch"))+"</button></form><div class=\"relative rounded-lg bg-[var(--console-card-bg)] p-3\"><div data-testid=\"graph-stage\" class=\"grid gap-3 lg:grid-cols-[minmax(0,1fr)_320px]\">")+PDL_COMPONENTS.v2Graph({label:tc("v2f.copy.w253"),view:[0,0,680,300],nodes:x.graph.nodes.map(function(n){return Object.assign({},n,{hub:n.selected,act:'set',args:{path:'cs.m.node',v:n.id}});}),edges:x.graph.edges},sc,root)+'<aside class="space-y-3 text-xs text-cafe-secondary"><h3 class="text-sm font-semibold">'+h(x.node)+'</h3><p>'+h(x.nodeDesc.join(' · '))+'</p>'+x.rels.map(function(r){return '<p>'+h(r.label)+' · '+h(r.value)+'</p>';}).join('')+'<div class="flex flex-wrap gap-2">'+x.rel.map(function(r){return '<label class="inline-flex items-center gap-1"><input type="checkbox"'+(r.on?' checked':'')+actAttrs('toggle',{path:'cs.m.rel.'+r.v})+'>'+h(r.label)+'</label>';}).join('')+'</div><p>'+h(x.nodeCount)+" "+tc("v2f.copy.w254")+" "+h(x.relationCount)+(" "+h(tc("v2f.copy.w255"))+"</p></aside></div></div></div>");};
PDL_COMPONENTS.v2SuggestionSummary=function(p,sc,root){const x=pv(p.data,sc,root);return ("<h2 class=\"text-sm font-semibold text-cafe\">"+h(tc("v2f.copy.w256"))+"</h2><p class=\"mt-1 text-xs text-cafe-secondary\">"+h(tc("v2f.copy.w257")))+h(V2_MISSION_STATUS[x.state])+'</p><h3 class="mt-3 text-sm font-semibold text-cafe">'+pvText(p.feature,sc,root)+'</h3><p class="mt-1 whitespace-pre-wrap text-sm text-cafe-secondary">'+h(x.sum)+'</p>'+(x.suggestion?'<div class="mt-4 space-y-2 rounded-lg bg-[var(--console-field-bg)] p-3 text-xs text-cafe-secondary"><strong>'+h(x.suggestion.catName)+' '+h(x.suggestion.catHandle)+("</strong><p>"+h(tc("v2f.copy.w258")))+h(x.suggestion.why)+("</p><p>"+h(tc("v2f.copy.w259")))+h(x.suggestion.plan)+'</p><p>'+h(x.suggestion.phase)+' · '+h(x.suggestion.status)+'</p>'+(x.suggestion.decided?'<p>'+h(x.suggestion.by)+' · '+h(x.suggestion.at)+'</p>':'')+(x.suggestion.hasNote?'<p>'+h(x.suggestion.note)+'</p>':'')+'</div>':'')+(x.hasThread?'<button class="mt-3 text-xs text-cafe-accent underline"'+actAttrs('thread',{id:x.thread})+'>'+h(x.threadTitle)+'</button>':'')+(x.leaseData?("<dl class=\"mt-4 space-y-1 rounded-lg bg-[var(--console-field-bg)] p-3 text-xs text-cafe-secondary\"><dt>"+h(tc("v2f.copy.w260"))+"</dt><dd>")+h(x.leaseData.name)+' · '+h(x.leaseData.state)+("</dd><dt>"+h(tc("v2f.copy.w261"))+"</dt><dd>")+h(x.leaseData.expiresAt)+("</dd><dt>"+h(tc("v2f.copy.w262"))+"</dt><dd>")+h(x.leaseData.beat)+'</dd></dl>':'')+'';};
