PDL_COMPONENTS.v2StudyFoldArea=function(p,sc,root){const x=pv(p.data,sc,root),button=function(label,act,args,cls){return '<button type="button" class="'+(cls||'rounded-md border border-cafe px-3 py-1.5 text-xs text-cafe-secondary hover:bg-cafe-surface-elevated')+'"'+actAttrs(act,args)+'>'+label+'</button>';};return '<details class="mt-4"'+(x.studyOpen?' open':'')+("><summary class=\"flex w-full cursor-pointer items-center justify-between rounded-t-lg bg-opus-bg px-3 py-2 text-xs font-semibold text-opus-dark\"><span>"+h(tc("v2f.copy.w263"))+" ")+h(x.study)+(" "+h(tc("v2f.copy.w033"))+"</span><span>")+h(x.lastStudyAt)+'</span></summary><div class="rounded-b-lg bg-cafe-surface-elevated p-3"><div class="flex flex-wrap gap-2">'+button(tc("v2f.copy.w264"),'wsDiscuss',{k:x.id,v:'learn'},'rounded-md bg-opus-primary px-3 py-1.5 text-xs font-semibold text-[var(--cafe-surface)] hover:bg-opus-dark')+button(tc("v2f.copy.w265"),'wsDiscuss',{k:x.id,v:'discuss'})+button(tc("v2f.copy.w266"),'wsDiscuss',{k:x.id,v:'multiCatResearch'})+'</div>'+(x.links.length?("<div class=\"mt-3\"><h4 class=\"text-xs font-semibold text-cafe-secondary\">"+h(tc("v2f.copy.w267"))+"</h4><ul class=\"mt-1 space-y-1\">")+x.links.map(function(t){return '<li class="flex items-center gap-1"><button class="flex flex-1 items-center justify-between rounded-md border border-cafe bg-cafe-surface px-3 py-1.5 text-xs text-opus-dark hover:bg-opus-bg"'+actAttrs('thread',{id:t.id})+'><span class="truncate">'+h(t.title)+'</span><span class="ml-2 shrink-0 text-cafe-muted">'+h(t.linkedAt)+'</span></button>'+button('×','remove',{entity:'sigLink',id:t.id},'shrink-0 rounded border border-conn-red-ring px-1.5 py-1 text-micro text-conn-red-text hover:bg-conn-red-bg')+'</li>';}).join('')+'</ul></div>':'')+'<div class="mt-3">'+PDL_COMPONENTS.v2Input({id:'ws-link',go:'add',args:{entity:'sigLink',k:x.id},placeholder:tc("v2f.copy.w268"),goLabel:tc("v2f.copy.w197")},sc,root)+'</div>'+(x.noteId?("<div class=\"mt-3\"><h4 class=\"text-xs font-semibold text-cafe-secondary\">"+h(tc("v2f.copy.w269"))+"</h4><details class=\"mt-1\"><summary class=\"flex w-full cursor-pointer items-center justify-between rounded-md border border-cafe bg-cafe-surface px-3 py-1.5 text-xs text-cafe-secondary\"><span>")+h(x.noteId)+'</span><span>'+h(x.noteDoneAt)+'</span></summary><pre class="mt-1 whitespace-pre-wrap rounded-md border border-cafe-subtle bg-cafe-surface-elevated px-3 py-2 text-xs text-cafe-secondary">'+h(x.noteSum)+'</pre></details></div>':'')+("<section class=\"mt-3\"><h4 class=\"text-xs font-semibold text-cafe-secondary\">"+h(tc("v2f.copy.w114"))+"</h4><div class=\"mt-2 flex gap-2\">")+button(tc("v2f.copy.w270"),'wsPodGen',{v:'brief'})+button(tc("v2f.copy.w271"),'wsPodGen',{v:'deep'})+'</div>'+(x.pod?'<div class="mt-2 rounded-lg border border-cafe-subtle p-3"><p class="text-xs text-cafe-secondary">'+h(x.pod.kind)+' · '+h(x.pod.minutes)+" "+tc("v2f.copy.w272")+" "+h(x.pod.count)+(" "+h(tc("v2f.copy.w273"))+"</p><div class=\"mt-2\">")+button(x.pod.playing?tc("v2f.copy.w274"):tc("v2f.copy.w275"),'toggle',{path:'ws.playAll'})+'</div><ul class="mt-2 space-y-1">'+x.pod.segs.map(function(s){return '<li class="rounded-md bg-[var(--console-field-bg)] px-3 py-2"><button class="text-xs font-medium text-opus-dark"'+actAttrs('set',{path:'ws.playing',v:s.i,cast:'num'})+'>'+h(s.title)+'</button><p class="mt-1 text-xs text-cafe-secondary">'+h(s.text)+'</p></li>';}).join('')+'</ul></div>':'')+'</section>'+(x.reports.length?("<div class=\"mt-3\"><h4 class=\"text-xs font-semibold text-cafe-secondary\">"+h(tc("v2f.copy.w115"))+"</h4><ul class=\"mt-1 space-y-1\">")+x.reports.map(function(r){return '<li class="rounded-md border border-cafe bg-cafe-surface px-3 py-1.5 text-xs text-cafe-secondary"><span class="font-medium">'+h(r.title)+'</span><span class="ml-2 text-cafe-muted">'+h(r.createdAt)+'</span></li>';}).join('')+'</ul></div>':'')+("<div class=\"mt-3\"><h4 class=\"text-xs font-semibold text-cafe-secondary\">"+h(tc("v2f.copy.w276"))+"</h4><ul class=\"mt-1 flex flex-wrap gap-1\">")+x.sets.map(function(s){return '<li class="rounded-full border border-opus-light bg-opus-bg px-2 py-0.5 text-xs text-opus-dark">'+h(s)+'</li>';}).join('')+'</ul><div class="mt-2">'+PDL_COMPONENTS.v2Select({id:'ws-set',change:'wsSetJoin',value:'',options:[{v:'',label:tc("v2f.copy.w277")}].concat(x.setOpts.map(function(s){return {v:s,label:s};}))},sc,root)+'</div><div class="mt-2">'+PDL_COMPONENTS.v2Input({id:'ws-new-set',go:'add',args:{entity:'sigSet',k:x.id},placeholder:tc("v2f.copy.w278"),goLabel:tc("v2f.copy.w133")},sc,root)+'</div></div></div></details>';};
PDL_COMPONENTS.v2SignalArticleDetail=function(p,sc,root){const x=pv(p.detail,sc,root);if(!x)return ("<aside class=\"rounded-xl border border-dashed border-[var(--console-border-soft)] bg-[var(--console-card-bg)] p-6 text-sm text-cafe-secondary\">"+h(tc("v2f.copy.w279"))+"</aside>");if(x.gone)return ("<aside class=\"rounded-xl bg-[var(--console-card-bg)] p-6 text-sm text-cafe-secondary\">"+h(tc("v2f.copy.w280"))+"</aside>");return '<aside class="rounded-xl bg-[var(--console-card-bg)] p-5 shadow-sm"><div class="flex flex-wrap items-center gap-2">'+PDL_COMPONENTS.v2SignalTierBadge({tier:x.tier},sc,root)+'<span class="rounded bg-[var(--console-field-bg)] px-2 py-0.5 text-xs font-medium text-cafe-secondary">'+h(x.state)+'</span></div><h2 class="mt-2 text-lg font-semibold text-cafe-black">'+h(x.title)+'</h2><p class="mt-1 text-xs text-cafe-secondary">'+h(x.source)+' · '+h(v2SignalDate(x.time))+'</p><div class="mt-2 flex flex-wrap gap-2">'+PDL_COMPONENTS.v2Action({label:tc("v2f.copy.w281"),act:'openUrl',args:{url:x.url},disabled:!x.url},sc,root)+PDL_COMPONENTS.v2Action({label:tc("v2f.copy.w265"),act:'wsDiscuss',args:{k:x.id,v:'discuss'},disabled:x.discussing},sc,root)+'</div>'+(x.sum?("<section class=\"mt-4 rounded-lg bg-[var(--console-field-bg)] p-3\"><h3 class=\"text-xs font-semibold text-cafe-black\">"+h(tc("v2f.copy.w282"))+"</h3><p class=\"mt-1 whitespace-pre-wrap text-sm text-cafe-black\">")+h(x.sum)+'</p></section>':'')+PDL_COMPONENTS.v2StudyFoldArea({data:{lit:x}},sc,root)+("<section class=\"mt-4\"><div class=\"flex items-center justify-between\"><h3 class=\"text-xs font-semibold text-cafe-secondary\">"+h(tc("v2f.copy.w283"))+"</h3><button class=\"text-xs text-opus-dark hover:underline\"")+actAttrs('wsSigRefresh',{k:x.id})+(">"+h(tc("v2f.copy.w284"))+"</button></div><div class=\"mt-1 max-h-[300px] overflow-y-auto rounded-lg bg-[var(--console-field-bg)] p-3 text-sm text-cafe-black\">")+mdHtml(x.body)+("</div></section><section class=\"mt-4\"><h3 class=\"text-xs font-semibold text-cafe-secondary\">"+h(tc("v2f.copy.w285"))+"</h3><div class=\"mt-2 flex flex-wrap gap-2\">")+x.tags.map(function(t){return '<span class="rounded-full border border-codex-light bg-codex-bg px-2 py-0.5 text-xs text-codex-dark">'+h(t.name)+'</span>';}).join('')+'</div><div class="mt-2 flex gap-2">'+PDL_COMPONENTS.v2Input({id:'ws-tag',go:'add',args:{entity:'sigTag',k:x.id},placeholder:tc("v2f.copy.w286"),goLabel:tc("v2f.copy.w286")},sc,root)+'</div></section><details class="mt-4"'+(x.noteOpen?' open':'')+("><summary class=\"flex cursor-pointer items-center gap-1 text-xs font-semibold text-cafe-secondary\">"+h(tc("v2f.copy.w287")))+(x.note?' '+icon('edit',12):'')+'</summary><div class="mt-2"><textarea class="w-full rounded-md border border-[var(--console-border-soft)] px-3 py-2 text-sm" rows="3" data-ws-note="'+h(x.id)+("\" placeholder=\""+h(tc("v2f.copy.w288"))+"\">")+h(x.note)+'</textarea>'+(x.noteSaved?("<output class=\"text-xs text-cafe-muted\">"+h(tc("v2f.copy.w289"))+"</output>"):'')+'</div></details><div class="mt-4 flex flex-wrap gap-2">'+[[tc("v2f.copy.w290"),'inbox'],[tc("v2f.copy.w291"),'read'],[tc("v2f.copy.w102"),'starred'],[tc("v2f.copy.w104"),'archived']].map(function(a){return PDL_COMPONENTS.v2Action({label:a[0],act:'setStatus',args:{entity:'sig',id:x.id,v:a[1]}},sc,root);}).join('')+PDL_COMPONENTS.v2Action({label:tc("v2f.copy.w292"),danger:true,act:'remove',args:{entity:'sig',id:x.id}},sc,root)+'</div></aside>';};
PDL_COMPONENTS.v2SignalSourceGroup=function(p,sc,root){const x=pv(p.record,sc,root);return '<div class="rounded-2xl bg-[var(--console-card-bg)] p-4 shadow-sm"><div class="mb-3 flex items-center gap-2">'+PDL_COMPONENTS.v2SignalTierBadge({tier:x.tier},sc,root)+'<h2 class="text-sm font-semibold text-cafe-black">'+h(x.category)+'</h2><span class="text-xs text-cafe-secondary">('+x.count+')</span></div><ul class="space-y-2">'+pvBlocks(p.rows,sc,root)+'</ul></div>';};
PDL_COMPONENTS.v2SignalSourceRow=function(p,sc,root){const x=pv(p.record,sc,root);return '<li class="rounded-xl bg-[var(--console-field-bg)] p-3"><div class="flex flex-wrap items-center justify-between gap-2"><div class="min-w-0"><p class="text-sm font-semibold text-cafe-black">'+h(x.name)+'</p><div class="mt-0.5 flex flex-wrap items-center gap-2"><a href="'+h(x.url)+'" target="_blank" rel="noopener noreferrer" class="break-all text-xs text-cafe-interactive hover:underline">'+h(x.url)+'</a><a href="'+h(x.url)+("\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"rounded-md border border-opus-light px-2 py-0.5 text-xs text-opus-dark hover:bg-opus-bg\">"+h(tc("v2f.copy.w293"))+"</a></div><p class=\"mt-1 text-xs text-cafe-secondary\">")+h(x.how)+' · '+h(x.freq)+'</p></div><div class="flex items-center gap-2"><button type="button" class="rounded-full border border-opus-light px-3 py-1 text-xs font-semibold text-opus-dark transition-colors hover:bg-opus-bg disabled:opacity-50"'+actAttrs('wsFetch',{k:x.id})+(x.busy?' disabled':'')+'>'+(x.busy?tc("v2f.copy.w294"):tc("v2f.copy.w295"))+'</button><button type="button" class="rounded-full border px-3 py-1 text-xs font-semibold transition-colors '+(x.on?'border-codex-light bg-codex-bg text-codex-dark':'border-[var(--console-border-soft)] bg-[var(--console-field-bg)] text-cafe-secondary')+'"'+actAttrs('setStatus',{entity:'src',id:x.id})+'>'+(x.on?tc("v2f.copy.w296"):tc("v2f.copy.w205"))+'</button></div></div></li>';};
