/* MarkdownContent.tsx element renderers. HTML from source text is escaped; code uses the old shell classes. */
function v2MarkdownHtml(src){
  const saved=[],hold=function(html){saved.push(html);return '\u0001'+(saved.length-1)+'\u0001';};
  const inline=function(text){let s=h(text).replace(/`([^`]+)`/g,function(_,code){const ref=v2MarkdownRef(code);if(ref)return hold(ref);return hold('<code class="bg-[var(--code-bg)] text-[var(--code-text)] rounded px-1 py-0.5 text-[0.85em] font-mono">'+code+'</code>');});s=v2MarkdownLinks(s,hold);s=s.replace(/\[([^\]]+)\]\(([^\s)]+)\)/g,function(_,label,url){return /^(?:https?:|mailto:|\/|#|\.\/)/.test(url)?'<a class="text-cafe-interactive underline underline-offset-2" href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a>':label;}).replace(/\*\*([^*]+)\*\*/g,'<strong class="font-semibold">$1</strong>').replace(/~~([^~]+)~~/g,'<del class="opacity-60">$1</del>').replace(/\*([^*]+)\*/g,'<em>$1</em>');s=s.replace(/(^|[^\w$])\$([^\s$](?:[^$]*?[^\s$])?)\$(?![\w$])/g,function(_,prefix,formula){return prefix+hold(mdRich('math',mdUnesc(formula),true));});return s;};
  const lines=String(src==null?'':src).split('\n'),out=[];
  for(let i=0;i<lines.length;i++){
    const line=lines[i];if(!line.trim())continue;
    if(i===0&&line==='---'){const fm=[];while(++i<lines.length&&lines[i]!=='---')fm.push(lines[i]);out.push('<pre class="mb-2 rounded-lg bg-cafe-surface-sunken p-3 font-mono text-xs">'+h(fm.join('\n'))+'</pre>');continue;}
    if(/^\s*\$\$\s*$/.test(line)){const math=[];while(++i<lines.length&&!/^\s*\$\$\s*$/.test(lines[i]))math.push(lines[i]);out.push(mdRich('math',math.join('\n')));continue;}
    if(/^\s*\|.*\|\s*$/.test(line)){const table=[line];while(i+1<lines.length&&/^\s*\|.*\|\s*$/.test(lines[i+1]))table.push(lines[++i]);const rows=table.filter(function(r){return !/^\s*\|?\s*:?-{2,}/.test(r);}),cells=function(r,tag){return r.replace(/^\s*\|/,'').replace(/\|\s*$/,'').split('|').map(function(c){return '<'+tag+' class="border border-cafe px-3 py-1.5 text-left">'+inline(c.trim())+'</'+tag+'>';}).join('');};out.push('<div class="overflow-x-auto my-2"><table class="min-w-full border-collapse text-sm"><thead class="bg-cafe-surface-sunken"><tr>'+cells(rows[0],'th')+'</tr></thead><tbody>'+rows.slice(1).map(function(r){return '<tr>'+cells(r,'td')+'</tr>';}).join('')+'</tbody></table></div>');continue;}
    const fence=/^```(\S*)/.exec(line);if(fence){const code=[];while(++i<lines.length&&!/^```/.test(lines[i]))code.push(lines[i]);const text=code.join('\n');if(fence[1]==='mermaid'){out.push(mdRich('mermaid',text));continue;}out.push('<div class="relative group my-2"><pre class="bg-cafe-surface-sunken text-cafe rounded-lg p-3 overflow-x-auto text-xs leading-5 font-mono"><code class="language-'+h(fence[1])+'">'+h(text)+'</code></pre></div>');continue;}
    const heading=/^(#{1,6})\s+(.*)/.exec(line);if(heading){const n=heading[1].length,cls=['','text-lg font-bold mb-2 mt-3 first:mt-0','text-base font-bold mb-2 mt-3 first:mt-0','text-sm font-bold mb-1 mt-2 first:mt-0','text-sm font-semibold mb-1 mt-2 first:mt-0','text-xs font-semibold mb-1 mt-1.5 first:mt-0 uppercase tracking-wide','text-xs font-medium mb-1 mt-1.5 first:mt-0 text-cafe-muted'][n];out.push('<h'+n+' class="'+cls+'">'+inline(heading[2])+'</h'+n+'>');continue;}
    if(/^\s*[-*_]{3,}\s*$/.test(line)){out.push('<hr class="my-3 border-cafe">');continue;}
    if(/^>\s?/.test(line)){const quote=[line.replace(/^>\s?/,'')];while(i+1<lines.length&&/^>\s?/.test(lines[i+1]))quote.push(lines[++i].replace(/^>\s?/,''));out.push('<blockquote class="border-l-[3px] border-cafe pl-3 my-2 italic opacity-80">'+inline(quote.join('\n'))+'</blockquote>');continue;}
    if(/^\s*(?:[-*+] |\d+\. )/.test(line)){const ordered=/^\s*\d+\./.test(line),tag=ordered?'ol':'ul',items=[line];while(i+1<lines.length&&/^\s*(?:[-*+] |\d+\. )/.test(lines[i+1]))items.push(lines[++i]);out.push('<'+tag+' class="'+(ordered?'list-decimal':'list-disc')+' pl-5 mb-2 space-y-0.5">'+items.map(function(s){return '<li>'+inline(s.replace(/^\s*(?:[-*+] |\d+\. )/,''))+'</li>';}).join('')+'</'+tag+'>');continue;}
    const para=[line];while(i+1<lines.length&&lines[i+1].trim()&&!/^(?:#{1,6} |```|> |[-*+] |\d+\. |\s*\|.*\||\s*\$\$)/.test(lines[i+1]))para.push(lines[++i]);out.push('<p class="mb-2 last:mb-0">'+inline(para.join('\n'))+'</p>');
  }
  return out.join('').replace(/\u0001(\d+)\u0001/g,function(_,i){return saved[+i];});
}
