function v2MarkdownRef(ref){const u=mdUnesc(ref),r=MD_REF.resolve?MD_REF.resolve(u,mdLinkTarget(u)):null;if(!r)return '';const t=PDL_FRAGS.refChip,act=pv(t.act,r,r);return '<button type="button" class="inline-flex max-w-full items-center gap-1 rounded-full border border-cafe-subtle bg-[var(--console-hover-bg)] px-2 py-0.5 text-xs text-cafe-secondary"'+(act?actAttrs(act,pvArgsObj(t.args,r,r)):' disabled')+' data-tip="'+pvText(t.tip,r,r)+'">'+v2Glyph(pv(t.icon,r,r))+v2Part(t.name,r,r)+'</button>';}
function v2MarkdownLinks(s,hold){let out='',i=0;while(i<s.length){const a=s.indexOf('[',i);if(a<0)break;const b=s.indexOf('](',a);if(b<0)break;const text=s.slice(a+1,b);if(text.includes('[')||text.includes('\n')||!text){out+=s.slice(i,a+1);i=a+1;continue;}let depth=1,j=b+2;for(;j<s.length&&depth;j++){if(s[j]==='(')depth++;else if(s[j]===')')depth--;else if(s[j]===' '||s[j]==='\n')break;}const url=depth?null:s.slice(b+2,j-1),target=url&&mdLinkTarget(mdUnesc(url));if(!target){out+=s.slice(i,a+1);i=a+1;continue;}out+=s.slice(i,a);const ref=v2MarkdownRef(url);if(ref)out+=hold(ref);else if(target.k==='url')out+=hold('<a class="text-cafe-interactive underline underline-offset-2" href="'+url+'" target="_blank" rel="noopener noreferrer">')+text+hold('</a>');else out+=hold('<button type="button" class="text-cafe-interactive underline underline-offset-2"'+actAttrs(target.k==='file'?'fileOpen':target.mid?'msgJump':'thread',target.k==='file'?{v:target.v}:target.mid?Object.assign({t:target.v,mid:target.mid},target.block?{block:target.block}:{}):{id:target.v})+'>')+text+hold('</button>');i=j;}return out+s.slice(i);}
function mdRich(kind,src,inline){const done=MD_RICH[kind+(inline?':i:':':b:')+src],tag=inline?'span':'div';return '<'+tag+' class="md-rich '+(inline?'':'my-2 overflow-x-auto')+'" data-rich="'+kind+'"'+(inline?' data-inline':'')+' data-src="'+h(src)+'"'+(done?' data-done':'')+'>'+(done||(inline?'<code class="rounded bg-cafe-surface-sunken px-1 font-mono text-xs">'+h(src)+'</code>':'<pre class="rounded-lg bg-cafe-surface-sunken p-3 font-mono text-xs"><code>'+h(src)+'</code></pre>'))+'</'+tag+'>';}

/* Selection annotations retain text-range geometry and use the v2 action drawing. */
function annotationHtml(html, annotations, markdown) {
  if (!annotations.length) return html;
  const root = document.createElement('div'); root.innerHTML = html;
  annotations.forEach(function (a) {
    const walk = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode: function (n) { return n.parentElement.closest('button') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; } }), nodes = [];
    let n, text = '';
    while ((n = walk.nextNode())) { nodes.push({ node: n, from: text.length, to: text.length + n.length }); text += n.data; }
    const positions = []; let compact = '';
    for (let i = 0; i < text.length; i++) if (!/\s/.test(text[i])) { positions.push(i); compact += text[i]; }
    const quote = document.createElement('div'); quote.innerHTML = markdown ? v2MarkdownHtml(a.quote) : h(a.quote);
    const needle = quote.textContent.replace(/\s/g, ''), at = compact.indexOf(needle);
    if (at < 0) return;
    const from = positions[at], to = positions[at + needle.length - 1] + 1; let last;
    nodes.forEach(function (s) {
      if (s.to <= from || s.from >= to) return;
      const r = document.createRange(), mark = document.createElement('mark'); mark.className = 'annotation-quote';
      r.setStart(s.node, Math.max(0, from - s.from)); r.setEnd(s.node, Math.min(s.node.length, to - s.from)); r.surroundContents(mark); last = mark;
    });
    last.insertAdjacentHTML('afterend', '<button type="button" class="annotation-mark inline-flex h-5 w-5 items-center justify-center rounded-full border border-opus-light bg-opus-bg text-opus-dark"'+(a.open?actAttrs(a.open.act,a.open.args):'')+' aria-label="'+h(a.speaking?tc('frame.speak'):a.label)+'">'+v2Glyph('inbox','h-3 w-3')+'</button>');
  });
  return root.innerHTML;
}

/* Fold placement/measurement remain the existing mechanism; the toggle is a v2 drawing. */
function foldTg(open,act,data,label,tip,shape){return '<button type="button" class="fold-tg mx-auto flex h-6 items-center justify-center gap-1 rounded-lg px-2 text-xs text-cafe-muted hover:bg-[var(--console-hover-bg)]"'+actAttrs(act,{})+(data||'')+' aria-expanded="'+open+'" aria-label="'+h(tip||tc(open?'common.collapse':'common.expand'))+'">'+v2Glyph('chevronDown','h-3 w-3'+(open?' rotate-180':''))+(label?'<span>'+label+'</span>':'')+'</button>';}
function foldBox(style,key,html,o){const open=!!S.folds[key],toggle=foldTg(open,'fold',argAttrs({k:key})),lines={s:3,m:5,l:8}[o.height]||8;if(style==='middle')return '<div class="fold" data-fold="middle" data-fold-key="'+h(key)+'" data-open="'+open+'"><div class="fold-head">'+html+'</div><div class="fold-tail" aria-hidden="true" inert><div class="fold-tail-in">'+html+'</div></div>'+toggle+'</div>';return '<div class="fold" data-fold="bottom" data-fold-key="'+h(key)+'" data-open="'+open+'" data-lines="'+lines+'"><div class="fold-in">'+html+'</div>'+toggle+'</div>';}
